{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_0",
      "quote": "The Delta variant (Phylogenetic Assignment of Named Global Outbreak (Pango) lineage designation B.1.617.2) of severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2) was first reported in October 2020 and has spread to more than 180 countries globally [1]. Concerns were raised about how well the currently available vaccines protect against this variant.",
      "reason": "The manuscript describes the current state (Delta variant emergence and global spread) and identifies an important uncertainty (concern about vaccine protection against Delta)."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_0",
      "quote": "Since January 2021, the Robert Koch Institute (RKI), in collaboration with the National Immunisation Technical Advisory Groups (NITAGs) network coordinated by the European Centre for Disease Prevention and Control (ECDC) is performing a living systematic review on the efficacy, effectiveness and safety of coronavirus disease (COVID-19) vaccines authorised in the European Union (EU) (PROSPERO registration: CRD42020208935) [2]. Here we present results on the effectiveness and the duration of protection provided by the EU-licensed COVID-19 vaccines in respect to the Delta variant.",
      "reason": "The manuscript explains the importance and need for the review (a living systematic review to summarise evidence on vaccine effectiveness against Delta) and states the review's purpose and registration."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PRESENT",
      "chunk_id": "text_13",
      "quote": "As already discussed in the first interim analysis [2] and given the highly dynamic publishing landscape in this field, we cannot exclude the possibility that additional published studies were not captured by our search strategy.",
      "reason": "The text refers to a prior (first interim) analysis and explicitly positions the current results in relation to that previous review, indicating awareness and citation of earlier similar work."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No text in the provided evidence describes the proposed mechanism of action of the intervention (vaccines)."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No text or figure in the provided evidence presents or mentions a logic model or hypothesised relationships between intervention components and outcomes."
    }
  ],
  "confidence": 85
}

